catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {

    if (isLoading) {
        return;
    }

    calculateMetroFare();
}


function calculateMetroFare() {

    var source =
        g_form.getValue('source_station');

    var destination =
        g_form.getValue('destination_station');

    var journeyType =
        g_form.getValue('journey_type');

    var passengers =
        g_form.getValue('passenger_count');


    // Clear previous calculated values before recalculating

    g_form.setValue(
        'calculated_distance',
        ''
    );

    g_form.setValue(
        'calculated_duration',
        ''
    );

    g_form.setValue(
        'calculated_fare',
        ''
    );


    // Wait until all required values are available

    if (
        !source ||
        !destination ||
        !journeyType ||
        !passengers
    ) {
        return;
    }


    // Source and destination cannot be same

    if (source == destination) {

        g_form.showFieldMsg(
            'destination_station',
            'Source and destination cannot be the same.',
            'error'
        );

        return;
    }


    var ga =
        new GlideAjax(
            'x_1958892_metro_0.MetroFareAjax'
        );


    ga.addParam(
        'sysparm_name',
        'calculateFare'
    );


    ga.addParam(
        'sysparm_source',
        source
    );


    ga.addParam(
        'sysparm_destination',
        destination
    );


    ga.addParam(
        'sysparm_journey_type',
        journeyType
    );


    ga.addParam(
        'sysparm_passengers',
        passengers
    );


    ga.getXMLAnswer(
        function(answer) {

            if (!answer) {

                g_form.addErrorMessage(
                    'Unable to calculate metro fare.'
                );

                return;
            }


            var result;

            try {

                result =
                    JSON.parse(answer);

            } catch (e) {

                g_form.addErrorMessage(
                    'Invalid fare calculation response.'
                );

                return;
            }


            if (!result.success) {

                g_form.addErrorMessage(
                    result.message
                );

                return;
            }


            g_form.setValue(
                'calculated_distance',
                result.distance + ' km'
            );


            g_form.setValue(
                'calculated_duration',
                result.duration + ' minutes'
            );


            g_form.setValue(
                'calculated_fare',
                '₹' + result.totalFare
            );
        }
    );
}
